async function confirmPaidPassV324(btn){
  if(btn.disabled)return;
  const id=Number(btn.dataset.passId),amount=Number(btn.dataset.price),label=btn.textContent||'';
  if(!Number.isSafeInteger(id)||id<=0||!Number.isFinite(amount)||amount<=0){alert('Neplatné údaje platby.');return}
  const retry=label.includes('skúsiť Meta');
  if(!retry&&!confirm('Potvrdzujete, že Chvostíkovo SKUTOČNE prijalo platbu '+amount.toFixed(2)+' € za túto permanentku? Samotné vytvorenie permanentky nestačí.'))return;
  btn.disabled=true;btn.textContent='Spracúvam úhradu…';
  try{
   const {data,error}=await withJwtRetry(()=>supabase.rpc('crm_confirm_payment_v324',{p_source_type:'pass',p_source_id:id,p_amount_eur:amount}));
   if(error)throw error;
   if(!data?.payment_id)throw new Error('Záznam platby sa nepodarilo overiť.');
   if(data.delivery_status==='no_consent'){btn.textContent='Platba potvrdená · bez Meta súhlasu';return}
   const sending=await withJwtRetry(()=>supabase.functions.invoke('meta-payment-event',{body:{payment_id:Number(data.payment_id)}}));
   if(sending.error||!sending.data?.ok){
    btn.disabled=false;btn.textContent='Platba potvrdená · skúsiť Meta znovu';
    alert('Úhrada je bezpečne uložená. Meta udalosť nebola potvrdená; tlačidlom môžete odoslanie zopakovať.');
    return;
   }
   if(sending.data.processing){btn.disabled=false;btn.textContent='Platba potvrdená · skúsiť Meta znovu';return}
   btn.textContent=sending.data.skipped?'Platba potvrdená · bez Meta súhlasu':'Platba potvrdená · Meta prijala';
  }catch(e){
   btn.disabled=false;btn.textContent=label;
   alert('Potvrdenie platby sa nepodarilo: '+String(e?.message||e));
  }
}
